var DATA = {"mode": "cpu", "name": "Signature Reference CPU", "codename": "JAH-C1", "nm": "5 nm", "cores": 8, "threads": 16, "base": 4.0, "boost": 5.2, "pkg": "JAH Socket"};
function show(k,v){console.log(k+": "+v);}
var m=DATA.mode;
if(m==="cpu"){
  console.log("CPU: "+DATA.name);
  show("Codename / process",DATA.codename+" / "+DATA.nm);
  show("Cores / threads",DATA.cores+" / "+DATA.threads);
