  show("Manufacturer",DATA.mfr);show("Model",DATA.model);
  show("Chipset",DATA.chipset);show("BIOS",DATA.bios);
}else if(m==="memory"){
  show("Type / size",DATA.type+" / "+DATA.size);
  show("Channels",DATA.ch);
  show("DRAM frequency",DATA.freq+" MHz (DDR "+(DATA.freq*2)+")");
}else if(m==="timings"){
  show("Primary timings","CL"+DATA.cl+"-"+DATA.trcd+"-"+DATA.trp+"-"+DATA.tras+" CR"+DATA.cr);
  show("tRFC",DATA.trfc+" clocks");
}else if(m==="spd"){
  console.log("Slot "+DATA.slot+": "+DATA.part);
  show("Manufacturer",DATA.mfr);
  show("Size / rank",DATA.size+" / "+DATA.rank);
  show("XMP / EXPO",DATA.xmp);
  show("Made","week "+DATA.week+" of "+DATA.year);
}else if(m==="bench"){
  show("Single thread",DATA.st);
  show("Multi thread",DATA.mt);
  show("MT/ST ratio",(Math.round(DATA.mt/DATA.st*100)/100)+"x across "+DATA.cores+" cores");
}else if(m==="validation"){
  show("Validation","submit to the public validator for a proof link");
  show("ID",DATA.valid);
}else if(m==="timers"){
  show("Check","QPC vs RTC vs HPET timer sanity");
  show("Result",DATA.res);
}else if(m==="graphics"){
  show("GPU",DATA.gpu);show("Clocks",DATA.clocks);
}else if(m==="instructions"){
  console.log("Instruction sets ("+DATA.sets.length+"):");
  DATA.sets.forEach(function(s){console.log("  "+s);});
}else if(m==="workflow"){
  console.log("Audit workflow:");
  DATA.steps.forEach(function(s,i){console.log("  "+(i+1)+". "+s);});
